#ifndef ASM101SA_TABLES_H
#define ASM101SA_TABLES_H

#include "common.h"

/*---------------------------------------------------------------------------
 * A mnemonic-keyed map.  Lookups happen in the code generator's innermost
 * loop, so an index is built on first use.
 */
typedef struct
{
  const char *key;
  asmint value;
} IntEntry;

typedef struct
{
  const IntEntry *entries;
  size_t n;
  int32_t *index; /* built lazily */
  size_t mask;
} IntMap;

int intmap_has (IntMap *m, const char *key);
asmint intmap_get (IntMap *m, const char *key, asmint dflt);

typedef struct
{
  const char *key;
  const char *value;
} StrEntry;

typedef struct
{
  const StrEntry *entries;
  size_t n;
} StrMap;

const char *strmap_get (const StrMap *m, const char *key);

typedef struct
{
  const char *key;
  asmint a;
  asmint b;
} PairEntry;

typedef struct
{
  const PairEntry *entries;
  size_t n;
} PairMap;

const PairEntry *pairmap_get (const PairMap *m, const char *key);

typedef struct
{
  const char *key;
  int known;
  unsigned char b0;
  unsigned char b1;
} CnopEntry;

typedef struct
{
  const CnopEntry *entries;
  size_t n;
} CnopMap;

const CnopEntry *cnopmap_get (const CnopMap *m, const char *key);

typedef struct
{
  const char *key;
  asmint subop;
  asmint mbit;
  int fieldFromOperand; /* the field comes from the first operand */
  asmint field;
} MscLongEntry;

typedef struct
{
  const MscLongEntry *entries;
  size_t n;
} MscLongMap;

const MscLongEntry *msclong_get (const MscLongMap *m, const char *key);

typedef enum
{
  BCE_IMMEDIATE,
  BCE_RELATIVE
} BceShortKind;

typedef struct
{
  const char *key;
  asmint opcode;
  int mbitIsIndex;
  asmint mbit;
  BceShortKind kind;
} BceShort1Entry;

typedef struct
{
  const BceShort1Entry *entries;
  size_t n;
} BceShort1Map;

const BceShort1Entry *bceshort1_get (const BceShort1Map *m, const char *key);

typedef enum
{
  BCE_ADDRESS,
  BCE_DISPCOUNT,
  BCE_IUACOMMAND,
  BCE_PARAMETER
} BceLayout;

typedef struct
{
  const char *key;
  asmint opcode;
  BceLayout layout;
} BceLongEntry;

typedef struct
{
  const BceLongEntry *entries;
  size_t n;
} BceLongMap;

const BceLongEntry *bcelong_get (const BceLongMap *m, const char *key);

/*---------------------------------------------------------------------------
 * The tables
 */
extern IntMap argsRR, rrBranchAliases, argsSRSandRS, argsSRSonly;
extern IntMap shiftOperations, branchAliases, argsRSonly, argsSRSorRS;
extern IntMap argsRI, argsSI, argsMSC, argsBCE;
extern IntMap mscMemory, mscImmediate, mscImmediate11, mscOpx, bceShort2;
extern IntMap literalDatatypeAlignments;
extern IntMap instructionsWithoutOperands, instructionsWithOperands;
extern IntMap knownInstructions, impliedR1;
extern IntMap bvcfAliases, fpOperations, fpOperationsSP, fpOperationsDP;
extern IntMap mscImmediateZeroOnly, mscImmediateIndexable;
extern StrMap appropriateRules;
extern CnopMap cnopFills;
extern PairMap mscBranch, pseudoOps;
extern MscLongMap mscLong;
extern BceShort1Map bceShort1;
extern BceLongMap bceLong;

/*---------------------------------------------------------------------------
 * Low-level machine-code generators.  Each fills `data` with the encoded
 * instruction and returns its length in bytes.  Each assumes without checking
 * that the fields it is handed are legitimate and in range.
 */
struct Val;
int generateSRS (struct Val *properties, const char *mnemonic, asmint r1,
                 asmint d2, asmint b2, unsigned char *data);
int generateRS0 (struct Val *properties, const char *mnemonic, asmint r1,
                 asmint d2, asmint b2, unsigned char *data);
int generateRS1 (struct Val *properties, const char *mnemonic, asmint ia,
                 asmint i, asmint r1, asmint d2, asmint x2, asmint b2,
                 unsigned char *data);
/* A branch alias has no opcode of its own in the long forms; the condition
   mask rides in R1 and the long form is simply a `BC` (or `BVC` for the
   aliases that test the overflow/carry register) with that mask. */
const char *rsMnemonic (const char *mnemonic);

/* `mnemonic.rstrip("$@#")` */
const char *stripSuffixes (const char *mnemonic);

#endif /* ASM101SA_TABLES_H */
